#!/usr/bin/env bash
# ams-morning-summary.sh — append the night's "## Chain -- <date>" section to the morning summary
# (spec §9: generated by the chain, pulled at session start through GET /health/morning-summary).
# Reads the last 24 h of receipts and the health stamp; ASCII '--' in headers on purpose.
set -eu
dir="$HOME/.mem0/maintenance"; mkdir -p "$dir"
python3 - "$dir" "${AMS_SUMMARY_NOW:-}" <<'PY'
import datetime as dt, json, sys
from pathlib import Path
d = Path(sys.argv[1]); now_s = sys.argv[2]
now = dt.datetime.fromisoformat(now_s.replace("Z", "+00:00")) if now_s else dt.datetime.now(dt.timezone.utc)
if now.tzinfo is None: now = now.replace(tzinfo=dt.timezone.utc)
cut = now - dt.timedelta(hours=24)
rows = []
try:
    for ln in (d / "receipts.jsonl").read_text(encoding="utf-8").splitlines():
        try: o = json.loads(ln)
        except ValueError: continue
        try: ts = dt.datetime.fromisoformat(str(o.get("ts", "")).replace("Z", "+00:00"))
        except ValueError: continue
        if ts.tzinfo is None: ts = ts.replace(tzinfo=dt.timezone.utc)
        if ts >= cut: rows.append(o)
except OSError: pass
def label(o):
    # `status` (outcome contract C1) says what exit 0 cannot: a step can run and do nothing.
    st = o.get("status") or ("ok" if o.get("ok") else "failed")
    return {"ok": "ok", "degraded": "DEGRADED"}.get(st, "FAILED")
def work(o):
    w = o.get("work")
    return (" [" + " ".join(f"{k}={v}" for k, v in w.items()) + "]") if isinstance(w, dict) and w else ""
lines = [f"- {o.get('step')} {label(o)} {o.get('duration_ms', 0)}ms{(' -- ' + o['note']) if o.get('note') else ''}{work(o)}" for o in rows] or ["- (no receipts in the last 24 h)"]
def names(h, key):
    return ",".join(str(x.get("step")) for x in h.get(key) or []) or "-"
def acked(h):
    a = (h.get("pool") or {}).get("health_ack") or {}
    return f" (acked until {a.get('until')})" if a.get("active") else ""
def write_path(h):
    # Named only when the server says the last real memory write failed; a healthy or unreadable tracker adds nothing.
    w = h.get("write_path")
    return " write-path " + " ".join(str((w.get("last_error") or "failing")).split()) if isinstance(w, dict) and w.get("ok") is False else ""
def capture(h):
    # Named only when the server says L1a has finished no run for days while PC sessions went on.
    c = h.get("capture")
    return f" capture stalled {c.get('success_age_h')}h" if isinstance(c, dict) and c.get("stalled") is True else ""
try:
    h = json.loads((d / "health-maintenance.json").read_text(encoding="utf-8"))
    lines.append(f"- health ok={h.get('ok')} stale={h.get('stale_steps')} failed={names(h, 'failed_steps')} degraded={names(h, 'degraded_steps')} pool {(h.get('pool') or {}).get('used_pct')}% usage {(h.get('usage') or {}).get('used_percent')}% pool-health {(h.get('pool') or {}).get('health', 'unknown')}{acked(h)}{write_path(h)}{capture(h)}")
except (OSError, ValueError): lines.append("- health stamp unavailable")
try:
    g = json.loads((d / "dream" / "gather.json").read_text(encoding="utf-8"))
    lines.append(f"- dream: {len(g.get('signals') or [])} signal(s), {g.get('tokens', 0)} tokens" + (" (dry run)" if g.get("dry_run") else ""))
except (OSError, ValueError): pass
with open(d / "morning-summary.md", "a", encoding="utf-8") as fh:
    fh.write(f"\n## Chain -- {now.strftime('%Y-%m-%d %H:%M')}\n" + "\n".join(lines) + "\n")
print(f"morning-summary: {len(rows)} receipt(s) summarised")
PY
